insert into auth.users(id)values('10000000-0000-4000-8000-000000000001'),('10000000-0000-4000-8000-000000000002');insert into projects(id,owner_id,name,research_type)values('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','One','CTI'),('20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002','Two','CTI'),('20000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000001','One B','CTI');
do $$declare c ioc_provider_connections;run record;payload jsonb;candidate uuid;begin insert into ioc_provider_connections(owner_id,provider_key,display_name,created_by)values('10000000-0000-4000-8000-000000000001','TEST_SYNTHETIC','Deterministic Test IOC Provider','10000000-0000-4000-8000-000000000001')returning * into c;select * into run from claim_ioc_connection(c.owner_id,c.id,'TEST');payload:=jsonb_build_array(jsonb_build_object('provider_item_id','one','candidate_type','IPV4','normalized_value','192.0.2.44','original_value','192.0.2[.]44','source_fingerprint',repeat('a',64),'confidence_score',50,'tags',jsonb_build_array('TEST'),'metadata','{}'::jsonb),jsonb_build_object('provider_skip_reason','INVALID_DATE_ORDER'));begin perform complete_ioc_ingestion(c.owner_id,c.id,run.run_id,gen_random_uuid(),'SUCCEEDED',run.cursor_version,'next',payload);raise exception 'wrong lease accepted';exception when others then if sqlerrm='wrong lease accepted'then raise;end if;end;perform complete_ioc_ingestion(c.owner_id,c.id,run.run_id,run.lease_token,'SUCCEEDED',run.cursor_version,'next',payload);select id into candidate from ioc_candidates where owner_id=c.owner_id;if candidate is null or(select count(*)from ioc_candidate_sources where candidate_id=candidate)<>1 or(select skipped_count from ioc_ingestion_runs where id=run.run_id)<>1 or(select count(*)from ioc_candidates where owner_id=c.owner_id)<>1 then raise exception 'candidate/skip-marker persistence failed';end if;perform set_config('request.jwt.claim.sub',c.owner_id::text,true);perform triage_ioc_candidate(candidate,'REVIEW');select * into run from claim_ioc_connection(c.owner_id,c.id,'TEST');perform complete_ioc_ingestion(c.owner_id,c.id,run.run_id,run.lease_token,'SUCCEEDED',run.cursor_version,'next2',payload);if(select status from ioc_candidates where id=candidate)<>'REVIEWED'or(select observation_count from ioc_candidate_sources where candidate_id=candidate)<>2 then raise exception 'triage/dedup failed';end if;if not(accept_ioc_candidate(candidate,'20000000-0000-4000-8000-000000000001','accept',null)->>'ok')::boolean then raise exception 'accept failed';end if;if(select status from indicators where project_id='20000000-0000-4000-8000-000000000001')<>'UNVERIFIED'or not exists(select 1 from indicator_observations where origin_kind='IMPORT')then raise exception 'indicator acceptance failed';end if;perform accept_ioc_candidate(candidate,'20000000-0000-4000-8000-000000000001','again',null);if(select count(*)from ioc_candidate_acceptances where candidate_id=candidate)<>1 or(select count(*)from indicator_observations where indicator_id=(select indicator_id from ioc_candidate_acceptances where candidate_id=candidate))<>1 then raise exception 'acceptance not idempotent';end if;perform accept_ioc_candidate(candidate,'20000000-0000-4000-8000-000000000003','second project',null);if(select count(*)from ioc_candidate_acceptances where candidate_id=candidate)<>2 then raise exception 'second project acceptance failed';end if;end$$;
-- Exact stale recovery, scheduler eligibility, source collision, counters, null-safe extrema and unexpected failure.
do $$declare c ioc_provider_connections; old_run record; new_run record; future ioc_provider_connections; disabled ioc_provider_connections; archived ioc_provider_connections; active ioc_provider_connections; due record; payload jsonb;begin
 c:=ensure_synthetic_ioc_connection('10000000-0000-4000-8000-000000000002');select * into old_run from claim_ioc_connection(c.owner_id,c.id,'MANUAL');
 begin perform claim_ioc_connection(c.owner_id,c.id,'MANUAL');raise exception 'active lease accepted';exception when others then if sqlerrm='active lease accepted'then raise;end if;end;
 update ioc_provider_connections set lease_expires_at=now()-interval '1 second'where id=c.id;update ioc_ingestion_runs set lease_expires_at=now()-interval '1 second'where id=old_run.run_id;
 select * into new_run from claim_ioc_connection(c.owner_id,c.id,'MANUAL');if(select status from ioc_ingestion_runs where id=old_run.run_id)<>'FAILED'or(select error_code from ioc_ingestion_runs where id=old_run.run_id)<>'LEASE_EXPIRED'then raise exception 'stale run not recovered';end if;
 begin perform fail_ioc_ingestion(c.owner_id,c.id,old_run.run_id,old_run.lease_token,'X','X');raise exception 'old run released new lease';exception when others then if sqlerrm='old run released new lease'then raise;end if;end;
 payload:=jsonb_build_array(jsonb_build_object('provider_item_id','extrema','candidate_type','DOMAIN','normalized_value','scheduler.example','original_value','scheduler.example','source_fingerprint',repeat('b',64),'confidence_score',20,'first_seen_at','2026-07-02T00:00:00Z','last_seen_at','2026-07-03T00:00:00Z','tags','[]'::jsonb,'metadata','{}'::jsonb));perform complete_ioc_ingestion(c.owner_id,c.id,new_run.run_id,new_run.lease_token,'SUCCEEDED',new_run.cursor_version,null,payload);
 update ioc_provider_connections set scheduler_enabled=true,next_scheduled_sync_at=now()-interval '1 second'where id=c.id;select * into due from claim_due_ioc_connections(20)where connection_id=c.id;if due.run_id is null or(select trigger_type from ioc_ingestion_runs where id=due.run_id)<>'SCHEDULED'then raise exception 'scheduled run missing';end if;perform fail_ioc_ingestion(due.owner_id,due.connection_id,due.run_id,due.lease_token,'TEST','safe');update ioc_provider_connections set scheduler_enabled=false,next_scheduled_sync_at=null where id=c.id;
 insert into ioc_provider_connections(owner_id,provider_key,display_name,enabled,scheduler_enabled,next_scheduled_sync_at,created_by)values(c.owner_id,'TEST_FUTURE','Future',true,true,now()+interval '1 hour',c.owner_id)returning * into future;insert into ioc_provider_connections(owner_id,provider_key,display_name,enabled,scheduler_enabled,next_scheduled_sync_at,created_by)values(c.owner_id,'TEST_DISABLED','Disabled',false,true,now()-interval '1 hour',c.owner_id)returning * into disabled;insert into ioc_provider_connections(owner_id,provider_key,display_name,enabled,scheduler_enabled,next_scheduled_sync_at,created_by,archived_at)values(c.owner_id,'TEST_ARCHIVED','Archived',true,true,now()-interval '1 hour',c.owner_id,now())returning * into archived;
 if exists(select 1 from claim_due_ioc_connections(20)x where x.connection_id in(future.id,disabled.id,archived.id))then raise exception 'ineligible scheduled connection claimed';end if;
end$$;
do $$declare c ioc_provider_connections;r record;payload jsonb;collision jsonb;candidate ioc_candidates;runrow ioc_ingestion_runs;begin perform set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);select * into c from ioc_provider_connections where provider_key='TEST_SYNTHETIC'and owner_id='10000000-0000-4000-8000-000000000002';select * into r from claim_ioc_connection(c.owner_id,c.id,'TEST');payload:=jsonb_build_array(jsonb_build_object('provider_item_id','extrema','candidate_type','DOMAIN','normalized_value','scheduler.example','original_value','scheduler.example','source_fingerprint',repeat('b',64),'confidence_score',90,'first_seen_at','2026-07-01T00:00:00Z','last_seen_at','2026-07-04T00:00:00Z','tags','[]'::jsonb,'metadata','{}'::jsonb),jsonb_build_object('bad','record'));select * into runrow from complete_ioc_ingestion(c.owner_id,c.id,r.run_id,r.lease_token,'SUCCEEDED',r.cursor_version,null,payload);select * into candidate from ioc_candidates where owner_id=c.owner_id and normalized_value='scheduler.example';if candidate.first_seen_at<>'2026-07-01T00:00:00Z'or candidate.last_seen_at<>'2026-07-04T00:00:00Z'or candidate.highest_confidence<>90 or runrow.candidate_count<>1 or runrow.updated_count<>1 or runrow.skipped_count<>1 or runrow.source_observation_count<>1 or runrow.deduplicated_count<>1 then raise exception 'extrema/counters incorrect';end if;
 select * into r from claim_ioc_connection(c.owner_id,c.id,'TEST');collision:=jsonb_build_array(jsonb_build_object('provider_item_id','collision','candidate_type','DOMAIN','normalized_value','other.example','original_value','other.example','source_fingerprint',repeat('b',64),'tags','[]'::jsonb,'metadata','{}'::jsonb));begin perform complete_ioc_ingestion(c.owner_id,c.id,r.run_id,r.lease_token,'SUCCEEDED',r.cursor_version,null,collision);raise exception 'collision accepted';exception when others then if sqlerrm='collision accepted'then raise;end if;end;if(select status from ioc_ingestion_runs where id=r.run_id)<>'RUNNING'then raise exception 'failed completion falsely succeeded';end if;perform fail_ioc_ingestion(c.owner_id,c.id,r.run_id,r.lease_token,'SOURCE_FINGERPRINT_COLLISION','safe');
 if(select count(*)from list_ioc_candidate_sources(candidate.id,100))<>1 or not exists(select 1 from list_ioc_inbox_v2(null,null,c.id,null,null,null,null,null,'confidence',null,null,30)where id=candidate.id)then raise exception 'detail/filter query failed';end if;
end$$;
create function public.phase2c_unexpected_failure()returns trigger language plpgsql as $$begin if new.normalized_value='unexpected.example'then raise exception 'PROGRAMMING_FAILURE';end if;return new;end$$;
create trigger phase2c_unexpected_failure before insert on ioc_candidates for each row execute function public.phase2c_unexpected_failure();
do $$declare c ioc_provider_connections;r record;payload jsonb;begin select * into c from ioc_provider_connections where provider_key='TEST_SYNTHETIC'and owner_id='10000000-0000-4000-8000-000000000002';select * into r from claim_ioc_connection(c.owner_id,c.id,'TEST');payload:=jsonb_build_array(jsonb_build_object('provider_item_id','unexpected','candidate_type','DOMAIN','normalized_value','unexpected.example','original_value','unexpected.example','source_fingerprint',repeat('c',64),'tags','[]'::jsonb,'metadata','{}'::jsonb));begin perform complete_ioc_ingestion(c.owner_id,c.id,r.run_id,r.lease_token,'SUCCEEDED',r.cursor_version,null,payload);raise exception 'unexpected failure swallowed';exception when others then if sqlerrm='unexpected failure swallowed'then raise;elsif sqlerrm<>'PROGRAMMING_FAILURE'then raise;end if;end;if(select status from ioc_ingestion_runs where id=r.run_id)<>'RUNNING'then raise exception 'unexpected failure falsely succeeded';end if;perform fail_ioc_ingestion(c.owner_id,c.id,r.run_id,r.lease_token,'PROVIDER_INTERNAL_FAILURE','safe');end$$;
drop trigger phase2c_unexpected_failure on ioc_candidates;drop function public.phase2c_unexpected_failure();
do $$begin if not exists(select 1 from pg_enum e join pg_type t on t.oid=e.enumtypid where t.typname='indicator_type'and e.enumlabel='CIDR')then raise exception 'CIDR missing';end if;if has_function_privilege('authenticated','public.complete_ioc_ingestion(uuid,uuid,uuid,uuid,public.ioc_ingestion_run_status,bigint,text,jsonb)','EXECUTE')then raise exception 'completion ACL';end if;if exists(select 1 from pg_class where relname like'ioc_%'and relkind='r'and not relrowsecurity)then raise exception 'RLS missing';end if;end$$;
